export interface InventoryItem { id: number; title: string; section: string; cost: number }
export interface InventoryQuery { sections: readonly string[]; page: number; pageSize: number }
export interface InventoryPage { data: InventoryItem[]; totalCount: number; totalPages: number }
export function selectInventory(items: readonly InventoryItem[], query: InventoryQuery): InventoryPage

Throw RangeError unless page and pageSize are integers, page is at least 1, and pageSize is between 1 and 100 inclusive. Trim section filters, discard empty filters, and compare sections case-insensitively. Duplicate filters have no additional effect. If no nonempty filters remain, all items match. Preserve input order before pagination. totalCount is the number of matches and totalPages is its ceiling division by pageSize, with zero matches producing zero pages. A page beyond the end has empty data. Return fresh item objects and do not mutate or alias any input, including the sections array.

