export interface InventoryItem {
  id: number;
  title: string;
  section: string;
  cost: number;
}

export interface InventoryQuery {
  sections: readonly string[];
  page: number;
  pageSize: number;
}

export interface InventoryPage {
  data: InventoryItem[];
  totalCount: number;
  totalPages: number;
}

export function selectInventory(
  items: readonly InventoryItem[],
  query: InventoryQuery,
): InventoryPage {
  if (!Number.isInteger(query.page) || query.page < 1 ||
      !Number.isInteger(query.pageSize) || query.pageSize < 1 || query.pageSize > 100) {
    throw new RangeError("invalid pagination");
  }

  const filters = new Set(
    query.sections.map((value) => value.trim().toLowerCase()).filter(Boolean),
  );
  const matches = items.filter(
    (item) => filters.size === 0 || filters.has(item.section.trim().toLowerCase()),
  );
  const totalCount = matches.length;
  const start = query.page * query.pageSize;

  return {
    data: matches.slice(start, start + query.pageSize).map((item) => ({ ...item })),
    totalCount,
    totalPages: totalCount === 0 ? 0 : Math.ceil(totalCount / query.pageSize),
  };
}

