import { selectInventory } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsRangeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const items = [
  { id: 1, title: 'A', section: 'Books', cost: 10 },
  { id: 2, title: 'B', section: 'Games', cost: 20 },
  { id: 3, title: 'C', section: 'BOOKS', cost: 30 },
  { id: 4, title: 'D', section: 'Books', cost: 40 },
];
const sections = [' books ', '', 'BOOKS', '  '];
const page = selectInventory(items, { sections, page: 2, pageSize: 2 });
deepEqual(page, {
  data: [{ id: 4, title: 'D', section: 'Books', cost: 40 }],
  totalCount: 3,
  totalPages: 2,
}, 'filtering, duplicate filters, order, and pagination');

items[3].title = 'Changed';
sections[0] = 'Games';
sections.push('Other');
deepEqual(page.data, [{ id: 4, title: 'D', section: 'Books', cost: 40 }], 'result does not alias items or filters');

const all = selectInventory(items, { sections: [' ', '\t'], page: 1, pageSize: 100 });
assert(all.totalCount === 4 && all.totalPages === 1 && all.data.length === 4, 'empty filters match all items');
assert(all.data[0] !== items[0], 'returned items are fresh objects');

const beyond = selectInventory(items, { sections: [], page: 3, pageSize: 2 });
deepEqual(beyond, { data: [], totalCount: 4, totalPages: 2 }, 'page beyond end');
const none = selectInventory(items, { sections: ['missing'], page: 1, pageSize: 1 });
deepEqual(none, { data: [], totalCount: 0, totalPages: 0 }, 'zero matches');

throwsRangeError(() => selectInventory(items, { sections: [], page: 0, pageSize: 1 }), 'page below one');
throwsRangeError(() => selectInventory(items, { sections: [], page: 1.5, pageSize: 1 }), 'fractional page');
throwsRangeError(() => selectInventory(items, { sections: [], page: 1, pageSize: 0 }), 'zero page size');
throwsRangeError(() => selectInventory(items, { sections: [], page: 1, pageSize: 101 }), 'page size above 100');
throwsRangeError(() => selectInventory(items, { sections: [], page: 1, pageSize: 2.5 }), 'fractional page size');

